function renderStatus(root){api("/user/reward/checkin/status").then(function(b){var d=b.data||{},s=root.querySelector("[data-reward-status]");if(!s)return;s.textContent=d.has_subscription===false?"当前没有可用订阅":"连续签到 "+(d.streak_days||0)+" 天 · 今日奖励 "+(d.next_reward_gb||d.reward_gb||0)+" GB"}).catch(function(){var s=root.querySelector("[data-reward-status]");if(s)s.textContent="签到状态暂时无法读取，请稍后重试"})}
